public static int Run(string folder){var r=new Dictionary<string,object>();bool passed=false;try{var req=O(J.DeserializeObject(File.ReadAllText(Path.Combine(folder,"request.json"))));dynamic l=Marshal.GetActiveObject("IronCAD.Application");var app=(IZBaseApp)l.ZIronCADApp;if(!app.ApiVersion.StartsWith("25."))throw new Exception("Wrong host");var doc=app.ActiveDoc;if(doc.Name!="Scene14")throw new Exception("Unexpected active prototype");Scene=(IZSceneDoc)doc;Pars=O(req["parameters"]);Nodes.Clear();Specs.Clear();foreach(var e in Children(Scene.GetTopElement())){if(!e.Name.StartsWith("RockPro / "))throw new Exception("Unknown element");Nodes[e.Name.Substring(10)]=e;}if(Nodes.Count!=72)throw new Exception("Incomplete prototype");foreach(var kv in Pars)Scene.ParameterMgr.GetParameterByName(kv.Key).Expression=Convert.ToDouble(kv.Value).ToString(System.Globalization.CultureInfo.InvariantCulture)+" mm";
foreach(var x in (object[])req["parts"]){var sp=O(x);string key=(string)sp["key"];Pose((IZSceneElement)Nodes[key],sp,1);Specs[key]=sp;}
foreach(var x in (object[])req["cuts"]){var c=O(x);var fm=(IZPartFeatureMgr)Nodes[(string)c["target"]];IZFeature found=null;for(int i=0;i<fm.GetFeaturesCount();i++)if(((IZElement)fm.GetFeatureAt(i)).Name=="RockPro wyciecie / "+c["key"])found=fm.GetFeatureAt(i);if(found==null)throw new Exception("Missing cut");Pose((IZSceneElement)found,c,2);}Update();
