foreach(var node in Nodes.Values)node.SetDirtyFlag(eZDirtyFlag.Z_DIRTY_GRAPHICS);Scene.Update();var cam=Scene.CameraMgr.ActiveCamera;cam.Perspective=false;cam.Position=new double[]{1.2,-1.2,.95};cam.Direction=new double[]{-.9,1.45,-.8};cam.Up=new double[]{0,0,1};cam.CenterOfInterest=new double[]{.3,.25,.15};Scene.AdjustCameraToFitShapeInRect(1280,800);Scene.UpdateGraphics(0);Scene.Redraw();r["unsaved"]=doc.Modified;r["document"]=doc.Name;r["parts_top_level"]=Nodes.Count;r["checks"]=checks;passed=true;}catch(Exception e){r["error"]=e.ToString();}r["passed"]=passed;File.WriteAllText(Path.Combine(folder,"result.json"),J.Serialize(r));return passed?0:1;}
}}
